# Exactly one pure read of the completed own coarse run; no solver/build/adoption or automatic follow-on.
$ErrorActionPreference='Stop';$tests=Split-Path -Parent $PSScriptRoot;$logs=Join-Path $tests 'logs';$tag='upl_damp_mid_CPU_coarse_r1';$cache=@{}
$review=Join-Path $tests ('outputs\'+$tag+'_native');$record=Join-Path $logs ($tag+'.native.json');$callPath=Join-Path $logs ($tag+'_reader.call.json');$log=Join-Path $logs ($tag+'_reader.log')
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function RawE([string]$p){$f=Get-Item -LiteralPath ([IO.Path]::GetFullPath($p)) -Force;Need (!$f.PSIsContainer) 'Expected a file';return [ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}
function E([string]$p){$key=([IO.Path]::GetFullPath($p)).ToLowerInvariant();if(!$cache.ContainsKey($key)){$cache[$key]=RawE $p};return $cache[$key]}
function V($rows){foreach($e in @($rows)){Need ($e.path -and $null -ne $e.bytes -and $e.sha256 -match '^[0-9a-fA-F]{64}$') 'Malformed Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed/conflicting Entry: '+$e.path)}}
function FinalV($rows){$seen=@{};foreach($e in @($rows)){$key=([IO.Path]::GetFullPath($e.path)).ToLowerInvariant();if(!$seen.ContainsKey($key)){$seen[$key]=RawE $e.path};$a=$seen[$key];Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed/conflicting final Entry: '+$e.path)}}
function J([string]$p){return ([IO.File]::ReadAllText($p)|ConvertFrom-Json)}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained artifact protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function N($v){if($v -is [ValueType]){$n=[double]$v}else{Need (![string]::IsNullOrWhiteSpace([string]$v)) 'Empty number';$n=[double]::Parse([string]$v,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture)};Need (![double]::IsNaN($n) -and ![double]::IsInfinity($n)) 'Nonfinite number';return $n}
Fresh @($review,$record,$callPath,$log);$runE=E (Join-Path $logs ($tag+'.run.json'));$r=J $runE.path;$c=J $r.call.path
Need ($r.passed -and $r.stage -ceq 'upl_damp_mid_run_r1' -and $r.backend -ceq 'CPU' -and $r.window -ceq 'coarse' -and $r.threads -eq 8 -and $r.configuration -ceq 'ReleaseCPU' -and $r.public_project_main -and !$r.fixture_or_Run_override -and $r.frozen_build_program_inputs_runtime_unchanged -and !$r.live_production_sources_frozen_by_this_run -and $r.locked_runtime_clock_values_verified -and !$r.step_candidate_adopted -and !$r.physical_acceptance) 'Own completed frozen CPU8 coarse Run required'
Need ($c.direct_native_call -and $c.owned_call_exited -and $c.typed_LASTEXITCODE_captured_immediately -and $c.exit_code -is [int] -and $c.exit_code -eq 0 -and !$c.invocation_failure -and $c.program.sha256 -ceq $r.program.sha256 -and $c.target_program.sha256 -ceq $r.program.sha256) 'Original direct actual typed solver exit0 required'
$helperE=E (Join-Path $logs 'upl_damp_mid_reader_ReleaseCPU_r1.helper.json');$h=J $helperE.path
Need ($h.passed -and $h.stage -ceq 'upl_damp_mid_reader_build_r1' -and $h.kind -ceq 'reader' -and $h.configuration -ceq 'ReleaseCPU' -and $h.exact_link_closure_verified -and $h.actual_headers_archived_not_live -and $h.project_header_include_remaps -eq 1 -and @($h.objects).Count -eq 85 -and $h.link_object_count -eq 86 -and @($h.runtime).Count -eq 4 -and $h.frozen_build_program_inputs_runtime_unchanged -and !$h.solver_started -and $h.source_build.sha256 -ceq $r.source_build.sha256) 'Same frozen-source archived-header mid reader85+1 required'
$dt=[Math]::Pow(2,-19);$steps=4798782;$end=[double]$steps*$dt
Need ($r.planned_completed_steps -eq $steps -and $r.expected_native_frames -eq 1746 -and $r.native_frames -eq 1746 -and $r.job.steps -eq $steps -and $r.job.dt_s -eq $dt -and $r.job.expected_samples -eq 1746 -and @($r.job.saved_clock_table).Count -eq 1746 -and @($r.source_snapshots265).Count -eq 265 -and @($r.retained_build_objects).Count -eq 86 -and @($r.runtime_copies).Count -eq 4) 'Own declared mid window/frozen closure differs'
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_mid_run_r1.json')),(E (Join-Path $tests 'notes\upl_damp_mid_r1.json')),$runE,$r.call,$helperE,$h.program,$h.helper_object,$h.compile_call,$h.link_call,$h.compiler_dependency_record,$h.source_build)+@($r.inputs)+@($r.files)+@($h.inputs)+@($h.objects)+@($h.actual_project_headers)
foreach($p in $h.runtime){$bindings+=@($p.original,$p.copy)};V $bindings
$data=Join-Path (Split-Path -Parent $r.run_out.path) 'data';$argv=@('--read','CPU',$data,'coarse',$review);$code=$null;$failure=$null;$started=[DateTime]::UtcNow.ToString('o');$saved=$ErrorActionPreference;[IO.File]::WriteAllBytes($log,[byte[]]@())
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $h.program.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$failure=$_.Exception.Message}finally{$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$h.program;arguments=$argv;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$failure;log=(E $log);pure_native_reader=$true;solver_or_build_invoked=$false})
# Seal the real reader exit before postchecks; analysis failure never restarts the completed solver.
$done=$null;$completion=$null;$files=@();$unchanged=$false;$historyRows=0;$jsonTimeMax=0.0;$jsonTimeDifferences=0
try{
  Need ($code -is [int] -and $code -eq 0 -and !$failure) 'Reader failed; preserve partial review'
  $completion=E (Join-Path $review 'completion.json');$done=J $completion.path
  Need ($done.passed -and $done.stage -ceq 'upl_damp_mid_native_r1' -and $done.backend -ceq 'CPU_public' -and $done.window -ceq 'mid' -and $done.preset -ceq 'coarse' -and $done.grid -ceq 'c' -and $done.samples -eq 1746 -and $done.native_count -eq 1000 -and $done.fixed_count -eq 40 -and $done.total_native_count -eq 1040 -and $done.physical_columns -eq 26 -and $done.physical_schema -ceq 'case02_common26_col21_ExcessPorePress_NOT_wave26' -and $done.native_total_arrays -eq 22 -and $done.PART_typed_public_metadata_verified -and $done.public_master_on -and $done.no_exclusions -and $done.all_exported_physical_fields_finite -and !$done.physical_acceptance) 'Original public22/native1040/finite/schema guards rejected'
  Need ($done.max_ledger_relative_error -le 5e-13 -and $done.soil_ledger_checks -eq 1746000 -and $done.fixed_public_zero_marker_checks -eq 69840 -and $done.dt_s -eq $dt -and [Math]::Abs((N $done.actual_end_s)-$end) -le 1e-14 -and $done.max_noninitial_signed_dterror_s -le 1e-14 -and $done.noninitial_signed_dterror_intervals -eq 1745 -and $done.actual_time_step_locked_dt_exact -and $done.planned_completed_steps -eq $steps -and $done.declared_saved_completed_steps_exact) 'Original ledger/signed necessary-step/end/preset guards rejected'
  $history=@(Import-Csv -LiteralPath (Join-Path $review 'history.csv'));$historyRows=$history.Count;Need ($historyRows -eq 1746) 'Native history count differs';$opened=0
  for($i=0;$i -lt 1746;$i++){
    $row=$history[$i];$step=[long]$row.completed_step;$expected=$r.job.saved_clock_table[$i];$savedStep=if($step -gt 0){$step-1}else{0};$wantedTime=[double]$step*$dt;$post=$step -gt 5243
    Need ([int]$row.part -eq $i -and [int]$expected.part -eq $i -and $step -eq [long]$expected.completed_steps -and [long]$expected.saved_step -eq $savedStep -and [long]$row.saved_step -eq $savedStep -and [BitConverter]::DoubleToInt64Bits((N $row.time_s)) -eq [BitConverter]::DoubleToInt64Bits($wantedTime) -and [BitConverter]::DoubleToInt64Bits((N $row.dt_s)) -eq [BitConverter]::DoubleToInt64Bits($dt)) 'Actual integer-dyadic mid native schedule differs'
    Need ([int]$row.activeDrainCount -eq $(if($post){10}else{0})) 'Original nonempty true drainage mask differs';$opened+=[int]$post
    $delta=[Math]::Abs((N $expected.time_s)-$wantedTime);$jsonTimeMax=[Math]::Max($jsonTimeMax,$delta);if($delta -ne 0){$jsonTimeDifferences++}
  }
  Need ($opened -eq 1542 -and $done.post_open_frames -eq 1542 -and $done.post_open_drained_particle_checks -eq 15420 -and $done.max_activeDrainCount -eq 10 -and $done.post_open_completed_step_threshold -eq 5243) 'Actual1746 post-opening coverage differs'
  $wanted=@('original15.bin','physical.bin','clock.bin','common_j_theta.bin','soil_n.bin','native_ids.csv','fixed_ids.csv','history.csv','ledger.csv','fixed_samples.csv','last_poro.csv','columns.csv','completion.json');$leaves=@(Get-ChildItem -LiteralPath $review -File);Need ($leaves.Count -eq 13 -and !(Compare-Object ($leaves.Name|Sort-Object) ($wanted|Sort-Object))) 'Native13 leaf set differs'
}catch{$failure=$_.Exception.Message}
try{FinalV $bindings;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}};if(Test-Path -LiteralPath $review){$files=@(Get-ChildItem -LiteralPath $review -File|Sort-Object Name|ForEach-Object{E $_.FullName})}
$passed=(!$failure -and $unchanged -and $null -ne $done)
Save $record ([ordered]@{stage='upl_damp_mid_native_run_r1';passed=[bool]$passed;backend='CPU';window='coarse';source_run=$runE;source_build=$r.source_build;reader_helper=$helperE;reader_call=(E $callPath);completion=$completion;inputs=$bindings;files=$files;paths=@{native_dir=$review;solver_dir=(Split-Path -Parent $r.run_out.path)};history_rows=$historyRows;original_native_guards_passed=[bool]$passed;drainage_nonempty_per_frame_verified=[bool]$passed;frozen_build_program_inputs_runtime_unchanged=$unchanged;live_production_sources_frozen_by_this_run=$false;live_production_or_canonical_rechecked=$false;independent_final_rehash_performed=$unchanged;reader_executed_by_this_action=$true;adopted_completed_reader=$false;dyadic_schedule_truth='integer completed_steps times locked binary dt, not transient PS JSON floating rowtime; typed C++ exact native clock retained';deserialized_JSON_time_differences_diagnostic=$jsonTimeDifferences;max_deserialized_JSON_time_difference_s_diagnostic=$jsonTimeMax;JSON_text_or_native_clock_modified=$false;planned_original_prefix_samples=1469;actual_prefix_proved=$false;independent_mid_half_or_theory_performed=$false;solver_or_build_invoked=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "Mid native review rejected; preserve $record/outputs, never rerun the solver"};Write-Output "One CPU mid native review sealed: $record"
